	ran, err := m.Run("", func(cmd string) error { seen = append(seen, cmd); return nil })
	want := []string{"go fmt ./...", "go vet ./...", "go build"}
	if err != nil || !slices.Equal(ran, want) || !slices.Equal(seen, want) {
